// Server-side billing calls (SPEC.md 5.1-5.2). The database functions enforce the
// money rules; inputs are validated here first so users get clear messages.
import { z } from "zod";
import { CURRENCIES, type Currency, type Money } from "./money";

export const PAYMENT_METHODS = ["cash", "mobile_money", "bank", "other"] as const;

export const paymentInput = z.object({
  /** Generated by the client so a retried request never creates a duplicate (CORE-06). */
  paymentId: z.uuid(),
  invoiceId: z.uuid(),
  amountMinor: z.bigint().positive("Amount must be greater than zero"),
  currency: z.enum(CURRENCIES),
  method: z.enum(PAYMENT_METHODS),
  reference: z.string().trim().max(120).optional(),
  receivedAt: z.date().optional(),
});
export type PaymentInput = z.infer<typeof paymentInput>;

export const voidInput = z.object({
  id: z.uuid(),
  reason: z.string().trim().min(3, "Give a reason of at least 3 characters").max(500),
});

export type RpcClient = {
  rpc(
    fn: string,
    args: Record<string, unknown>,
  ): PromiseLike<{ data: unknown; error: { message: string } | null }>;
};

export class BillingError extends Error {
  override name = "BillingError";
}

async function call(
  client: RpcClient,
  fn: string,
  args: Record<string, unknown>,
): Promise<unknown> {
  const { data, error } = await client.rpc(fn, args);
  if (error) throw new BillingError(error.message);
  return data;
}

/** Issues a draft invoice and returns its number (CORE-08). */
export async function issueInvoice(client: RpcClient, invoiceId: string): Promise<number> {
  const data = await call(client, "issue_invoice", { p_invoice_id: z.uuid().parse(invoiceId) });
  return Number(data);
}

export type PaymentResult = {
  paymentId: string;
  receiptId: string;
  receiptNumber: number;
  invoiceStatus: "issued" | "partially_paid" | "paid";
};

const paymentRow = z.object({
  payment_id: z.string(),
  receipt_id: z.string(),
  receipt_number: z.union([z.number(), z.string()]),
  invoice_status: z.enum(["issued", "partially_paid", "paid"]),
});

/** Records a payment and issues its receipt; safe to retry with the same paymentId. */
export async function recordPayment(
  client: RpcClient,
  input: PaymentInput,
): Promise<PaymentResult> {
  const p = paymentInput.parse(input);
  const data = await call(client, "record_payment", {
    p_payment_id: p.paymentId,
    p_invoice_id: p.invoiceId,
    // Sent as a string so amounts beyond 2^53 survive JSON.
    p_amount_minor: p.amountMinor.toString(),
    p_currency: p.currency,
    p_method: p.method,
    p_reference: p.reference ?? null,
    p_received_at: p.receivedAt?.toISOString() ?? null,
  });
  const row = paymentRow.parse(Array.isArray(data) ? data[0] : data);
  return {
    paymentId: row.payment_id,
    receiptId: row.receipt_id,
    receiptNumber: Number(row.receipt_number),
    invoiceStatus: row.invoice_status,
  };
}

/** Voids a posted payment with a reason; returns the invoice's new status (CORE-07). */
export async function voidPayment(
  client: RpcClient,
  paymentId: string,
  reason: string,
): Promise<string> {
  const v = voidInput.parse({ id: paymentId, reason });
  return String(await call(client, "void_payment", { p_payment_id: v.id, p_reason: v.reason }));
}

/** Voids an invoice with no posted payments (CORE-07). */
export async function voidInvoice(
  client: RpcClient,
  invoiceId: string,
  reason: string,
): Promise<void> {
  const v = voidInput.parse({ id: invoiceId, reason });
  await call(client, "void_invoice", { p_invoice_id: v.id, p_reason: v.reason });
}

/** Balance due from an `invoice_balances` row, in the invoice's currency. */
export function balanceDue(row: {
  currency: Currency;
  total_minor: string | number;
  paid_minor: string | number;
}): Money {
  return { amountMinor: BigInt(row.total_minor) - BigInt(row.paid_minor), currency: row.currency };
}
